'use client';
import { useState } from 'react';

export default function AduanasPage() {
    const [loading, setLoading] = useState(false);
    const [mensaje, setMensaje] = useState(null);

    const subirArchivo = async (e) => {
        const file = e.target.files[0];
        if (!file) return;

        setLoading(true);
        setMensaje(null);

        const formData = new FormData();
        formData.append('file', file);

        try {
            const res = await fetch('/api/extract-invoice', { 
                method: 'POST', 
                body: formData 
            });

            if (!res.ok) {
                const errorData = await res.json().catch(() => ({ error: 'Error procesando el archivo' }));
                throw new Error(errorData.error || 'Error al procesar la factura.');
            }

            // Capturar el archivo binario enviado por la API
            const blob = await res.blob();
            
            // Obtener el nombre del archivo desde las cabeceras (Content-Disposition) o asignar uno por defecto
            const contentDisposition = res.headers.get('Content-Disposition');
            let fileName = 'factura_extraida.csv';
            if (contentDisposition && contentDisposition.includes('filename=')) {
                fileName = contentDisposition.split('filename=')[1].replace(/"/g, '');
            } else {
                fileName = file.name.replace(/\.[^/.]+$/, "") + '_bd.csv';
            }

            // Crear un enlace temporal en memoria para forzar la descarga en el navegador
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = fileName;
            document.body.appendChild(a);
            a.click();
            a.remove();
            window.URL.revokeObjectURL(url);

            setMensaje({ tipo: 'éxito', texto: `¡Descarga iniciada! (${fileName})` });

        } catch (error) {
            setMensaje({ tipo: 'error', texto: error.message });
        } finally {
            setLoading(false);
            // Limpiar el input para permitir volver a subir el mismo u otro archivo
            e.target.value = '';
        }
    };

    return (
        <main 
            style={{ 
                background: '#f1f5f9',
                minHeight: '100vh', 
                width: '100%', 
                display: 'grid', 
                placeItems: 'center', 
                padding: '1.5rem 1rem',
                boxSizing: 'border-box'
            }}
        >
            {/* Contenedor siempre centrado */}
            <div className="max-w-xl w-full space-y-4">
                
                {/* TARJETA DE INTRODUCCIÓN COMPACTA */}
                <div className="bg-white rounded-xl shadow-md border border-slate-200/80 p-5 text-center text-slate-800">
                    <div className="inline-flex items-center justify-center w-10 h-10 rounded-lg bg-sky-100 text-sky-600 mb-2 border border-sky-200 shadow-sm">
                        ⚡
                    </div>
                    <h2 className="text-xl md:text-2xl font-extrabold tracking-tight text-slate-900">
                        LogisParse: Extracción Híbrida
                    </h2>
                    <p className="text-xs md:text-sm text-slate-500 mt-1 max-w-sm mx-auto">
                        Procesamiento local seguro. Carga tu factura y obtén la base de datos descargada directamente.
                    </p>
                </div>

                {/* TARJETA DE CARGA */}
                <div className="bg-white rounded-xl shadow-md border border-slate-200/80 p-5 md:p-6 text-slate-800">
                    
                    {/* Zona de carga */}
                    <div className="relative border-2 border-dashed border-sky-300 hover:border-sky-500 transition-colors duration-200 rounded-lg p-6 bg-sky-50/30 text-center cursor-pointer group">
                        <input 
                            type="file" 
                            accept=".pdf, image/jpeg, image/png" 
                            onChange={subirArchivo} 
                            disabled={loading} 
                            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer disabled:cursor-not-allowed" 
                        />
                        <div className="flex flex-col items-center justify-center space-y-1.5">
                            <div className="p-2 bg-white rounded-full border border-sky-200 shadow-sm group-hover:scale-105 transition-transform">
                                📄
                            </div>
                            <p className="text-xs md:text-sm font-medium text-slate-700">
                                Arrastra tu factura o <span className="text-sky-600 font-semibold underline">haz clic para buscar</span>
                            </p>
                            <p className="text-[11px] text-slate-400">Soporta PDF, PNG y JPG</p>
                        </div>
                    </div>

                    {/* Feedback de Carga */}
                    {loading && (
                        <div className="mt-4 p-3 rounded-lg bg-sky-50 border border-sky-200 flex items-center justify-center space-x-2 shadow-sm">
                            <span className="animate-spin text-base">⚙️</span>
                            <p className="text-xs text-sky-800 font-medium">
                                Procesando factura y generando archivo...
                            </p>
                        </div>
                    )}

                    {/* Mensaje de Estado / Notificación de Descarga */}
                    {mensaje && (
                        <div className={`mt-4 p-3 rounded-lg border text-center text-xs font-medium shadow-sm ${
                            mensaje.tipo === 'éxito' 
                                ? 'bg-emerald-50 border-emerald-200 text-emerald-800' 
                                : 'bg-rose-50 border-rose-200 text-rose-800'
                        }`}>
                            {mensaje.tipo === 'éxito' ? '✅ ' : '❌ '}
                            {mensaje.texto}
                        </div>
                    )}

                </div>
            </div>
        </main>
    );
}